struct chunk_file {};

class stringx {
public:
  stringx();
  stringx(const char *, int = -1);
  ~stringx();
  bool operator==(const stringx&) const;
  bool operator!=(const stringx&) const;
private:
  char *data;
  void *buffer;
};

extern const stringx chunkend_label;
void serial_in(chunk_file&, stringx*);
void serial_in(chunk_file&, int*);

class entity {
public:
  bool parse_instance(const stringx&, chunk_file&);
};

class item : public entity {
  char padding[0x214];
  int count;
public:
  bool parse_instance(const stringx&, chunk_file&);
};

bool item::parse_instance( const stringx& pcf, chunk_file& fs )
{
  if ( pcf == stringx("item") )
  {
    stringx cf;
    for ( serial_in(fs,&cf); cf!=chunkend_label; serial_in(fs,&cf) )
    {
      if ( cf == stringx("count") )
      {
        serial_in( fs, &count );
      }
    }
  }
  else
    return entity::parse_instance( pcf, fs );

  return true;
}
